package com.houyidb.client;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;

class StableIdTest {

    /**
     * stable_id 六方对拍：期望值由 Python SDK（hashlib.blake2b(digest_size=8)）
     * 生成，与 TS/Go/Rust/.NET SDK、服务端网关同算法。跨语言一致是 delete 重放的前提。
     * EN: stable_id cross-check across six parties: the expected values are
     * generated by the Python SDK (hashlib.blake2b(digest_size=8)); the same
     * algorithm as the TS/Go/Rust/.NET SDKs and the server gateway. Cross-language
     * agreement is what makes delete replay possible.
     */
    @ParameterizedTest(name = "stable_id({0})")
    @CsvSource({
        "'', 7252660547403494068",
        "hello, 2861735919082615933",
        "node-42, 6694704320175634731",
        "苹果香蕉, 4490440666094115033",
        "doc-1, 6265767295393789249",
        "a/b?c#d, 4199517732852746375",
    })
    void matchesPythonSdk(String text, long want) {
        assertEquals(want, StableId.of(text));
    }

    @Test
    void deterministicAndPositiveHalf() {
        long a = StableId.of("same-input");
        assertEquals(a, StableId.of("same-input"));
        assertTrue(a >= 0, "masked to positive half, signed long must stay non-negative");
    }

    @Test
    void quotePathSegmentEncodesReserved() {
        assertEquals("docs", HouyiClient.quotePathSegment("docs"));
        assertEquals("a%2Fb%3Fc%23d", HouyiClient.quotePathSegment("a/b?c#d"));
        assertEquals("%E7%A9%BA%20%E9%97%B4", HouyiClient.quotePathSegment("空 间"));
    }
}
